/**
 * @summary Crea el cliente del usuario (alta desde el portal) o un cliente sin cuenta (rol comercial). Spec 001.
 */
export const crearCliente = async (clienteNuevo: ClienteNuevo, options?: Parameters<typeof pedirViajes>[1]): Promise<Cliente> => {
  const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]));
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return pedirViajes<Cliente>(getCrearClienteUrl(), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(clienteNuevo),
  });
};

