/**
 * Responde 202 al iniciar el workflow. Con la misma clave y el mismo cuerpo todavía EN_PROCESO, vuelve a
 * llamar `start` con el mismo workflowId y responde otra vez 202 con el mismo servicioId (D43).
 * @summary Confirma una cotización e inicia la saga ProgramarViaje. Spec 003.
 */
export const crearServicio = async (
  servicioNuevo: ServicioNuevo,
  options?: Parameters<typeof pedirViajes>[1],
): Promise<ServicioAceptado> => {
  const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]));
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return pedirViajes<ServicioAceptado>(getCrearServicioUrl(), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(servicioNuevo),
  });
};

